(function(){
'use strict';
function init(){
 var work=document.querySelector('#sidebar .menu[data-page="work"]');if(!work||document.getElementById('namo-production-result-menu'))return;
 var menu=document.createElement('div');menu.id='namo-production-result-menu';menu.className='menu';menu.innerHTML='<div class="ico">📊</div><div class="label">생산실적 현황</div>';work.insertAdjacentElement('afterend',menu);
 var panel=document.createElement('section');panel.id='namo-production-result-panel';panel.className='module-page';panel.style.cssText='background:#fff;padding:16px 18px;min-height:100%;font-family:inherit';
 panel.innerHTML="<style>\n#namo-production-result-panel{padding:0!important;background:#fff!important}\n#namo-production-result-panel .npr-head{display:flex;align-items:center;justify-content:space-between;padding:17px 22px;border-bottom:1px solid #d7e1eb}\n#namo-production-result-panel .npr-head h2{font-size:18px;color:#163e66;margin:0;border-left:3px solid #1376c4;padding-left:12px;font-weight:750}\n#namo-production-result-panel .npr-filters{display:flex;align-items:center;gap:14px;flex-wrap:wrap;background:#f1f6fb;padding:13px 16px;border-bottom:1px solid #d7e1eb}\n#namo-production-result-panel label{display:flex;align-items:center;gap:8px;font-size:12px;font-weight:650;color:#3b5670;flex:1;min-width:190px;white-space:nowrap}\n#namo-production-result-panel input,#namo-production-result-panel select{min-width:0;flex:1;height:34px;border:1px solid #cbd8e8;border-radius:4px;background:white;padding:0 10px;color:#344c64}\n#namo-production-result-panel button{cursor:pointer;background:white;border:1px solid #cbd9ea;border-radius:4px;color:#27537d;padding:8px 12px;font-weight:650}\n#namo-production-result-panel .npr-toolbar{display:flex;align-items:center;justify-content:space-between;padding:14px 16px;color:#173e67;font-size:13px;font-weight:750}\n#namo-production-result-panel .npr-table-wrap{padding:0 16px;overflow:auto}\n#namo-production-result-panel table{border-collapse:collapse;width:100%;font-size:12px}\n#namo-production-result-panel th{background:#e6eef7;color:#173f64;border:1px solid #cbd9e6;padding:12px 7px;white-space:nowrap;text-align:center}\n#namo-production-result-panel td{border:1px solid #d7e1eb;padding:13px 7px;text-align:center;color:#42546b}\n#namo-production-result-panel tbody tr:nth-child(even){background:#f9fbfd}\n#namo-production-result-panel tbody tr:hover{background:#eff6ff}\n#namo-production-result-panel .nprWorkLink{color:#0874c7;border:0;background:none;text-decoration:underline;padding:0}\n#namo-production-result-panel .npr-pages{display:flex;justify-content:center;gap:5px;margin:18px}\n#namo-production-result-panel .npr-pages button.active{background:#277bd0;color:white;border-color:#277bd0}\n\n#namo-production-result-panel .npr-filters{flex-wrap:nowrap;gap:12px}#namo-production-result-panel .npr-filters label{min-width:0;flex:1}#namo-production-result-panel .npr-date-label{position:relative;flex:1.1!important}#namo-production-result-panel .npr-date-toggle{width:100%;display:flex;justify-content:space-between;align-items:center;height:34px;text-align:left;font-weight:500}#namo-production-result-panel .npr-date-popover{position:absolute;top:38px;right:0;z-index:30;background:white;border:1px solid #cbd9e8;border-radius:6px;box-shadow:0 8px 22px #193d6022;padding:12px;min-width:280px;white-space:normal}#namo-production-result-panel .npr-date-popover[hidden]{display:none}#namo-production-result-panel .npr-date-popover span{display:flex;align-items:center;gap:8px;margin-bottom:8px}#namo-production-result-panel .npr-date-popover input{max-width:190px}#namo-production-result-panel .npr-toolbar button{height:34px}#namo-production-result-panel .npr-filters input,#namo-production-result-panel .npr-filters select{font-weight:400}#namo-production-result-panel td{font-weight:400}#namo-production-result-panel .npr-toolbar{padding:12px 16px}@media(max-width:1100px){#namo-production-result-panel .npr-filters{flex-wrap:wrap}#namo-production-result-panel .npr-filters label{min-width:180px}}\n</style>\n<div class=\"npr-head\"><h2>생산실적 현황</h2><button id=\"nprExport\">엑셀 내보내기</button></div>\n<div class=\"npr-filters\">\n<label>작업지시번호 <input id=\"nprWork\" placeholder=\"전체\"></label>\n<label>제품명 <input id=\"nprProduct\" placeholder=\"전체\"></label>\n<label>생산 LOT <input id=\"nprLot\" placeholder=\"전체\"></label>\n<label>작업상태 <select id=\"nprStatus\"><option value=\"\">전체</option><option>완료</option><option>대기</option><option>진행중</option></select></label>\n<label class=\"npr-date-label\">작업기간 <button type=\"button\" id=\"nprDateToggle\" class=\"npr-date-toggle\">기간 선택 <span aria-hidden=\"true\">▦</span></button><span id=\"nprDatePopover\" class=\"npr-date-popover\" hidden><span>시작일 <input id=\"nprStart\" type=\"date\"></span><span>종료일 <input id=\"nprEnd\" type=\"date\"></span><button type=\"button\" id=\"nprDateApply\">적용</button><button type=\"button\" id=\"nprDateClear\">초기화</button></span></label>\n</div>\n<div class=\"npr-toolbar\"><span>▸ 생산실적 현황 <small id=\"nprCount\"></small></span><span><button id=\"nprReset\">조건 지우기</button> <button id=\"nprRefresh\" title=\"조회\" aria-label=\"조회\">⌕</button> <button id=\"nprCollapse\" title=\"현황 접기\" aria-label=\"현황 접기\">⌃</button></span></div>\n<div class=\"npr-table-wrap\"><table><thead><tr><th>No.</th><th>작업일자</th><th>작업지시번호</th><th>제품명</th><th>생산 LOT NO</th><th>계획수량(kg)</th><th>실제 생산수량(kg)</th><th>달성률</th><th>작업상태</th></tr></thead><tbody id=\"nprRows\"></tbody></table></div>\n<div id=\"nprPages\" class=\"npr-pages\"></div><div id=\"nprError\" style=\"padding:8px 18px;color:#a33\"></div>";
 var host=document.querySelector('#work')?.parentElement||document.querySelector('main')||document.body;host.appendChild(panel);
 var esc=v=>String(v==null?'':v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 var val=(o,keys)=>{for(var k of keys){if(o[k]!=null&&o[k]!=='')return o[k];if(o.fields&&o.fields[k]!=null&&o.fields[k]!=='')return o.fields[k]}return ''};
 function num(v){if(v===''||v==null)return null;var n=Number(String(v).replace(/,/g,''));return Number.isFinite(n)?n:null}
 var allRows=[],page=1,filtered=[];
 function matches(o,id,keys){return String(val(o,keys)).toLowerCase().includes(document.getElementById(id).value.trim().toLowerCase())}
 function filter(){var start=document.getElementById('nprStart').value,end=document.getElementById('nprEnd').value,st=document.getElementById('nprStatus').value;filtered=allRows.filter(o=>{var d=String(val(o,['workDate','작업일자','작업기간'])).slice(0,10);return matches(o,'nprWork',['workNo','workOrderNo','작업지시번호'])&&matches(o,'nprProduct',['productName','제품명'])&&matches(o,'nprLot',['lotNo','productionLot','생산 LOT NO'])&&(!st||String(val(o,['status','진행상태']))===st)&&(!start||d>=start)&&(!end||d<=end)});page=1;draw()}
 function draw(){
  var body=document.getElementById('nprRows');document.getElementById('nprCount').textContent='('+filtered.length+'건)';
  var slice=filtered.slice((page-1)*10,page*10);
  body.innerHTML=slice.map((o,i)=>{var planned=num(val(o,['plannedQty','planQty','계획수량(kg)','계획수량'])),actual=num(val(o,['actualQty','producedQty','productionQty','실제생산수량','생산수량(kg)','생산수량']));var cells=[(page-1)*10+i+1,String(val(o,['workDate','작업일자','작업기간'])).slice(0,10)||'-',val(o,['workNo','workOrderNo','작업지시번호'])||o.id||'-',val(o,['productName','제품명'])||'-',val(o,['lotNo','productionLot','생산 LOT NO'])||'-',planned===null?'미등록':planned.toLocaleString(),actual===null?'미등록':actual.toLocaleString(),planned>0&&actual!==null?(actual/planned*100).toFixed(1)+'%':'-',val(o,['status','진행상태'])||'-'];return '<tr>'+cells.map((c,j)=>'<td>'+(j===2?'<button class="nprWorkLink">'+esc(c)+'</button>':esc(c))+'</td>').join('')+'</tr>'}).join('')||'<tr><td colspan="9">조회 결과가 없습니다.</td></tr>';
  var pages=document.getElementById('nprPages'),total=Math.ceil(filtered.length/10);pages.innerHTML='';for(let i=1;i<=total;i++){var btn=document.createElement('button');btn.textContent=i;btn.className=i===page?'active':'';btn.onclick=()=>{page=i;draw()};pages.appendChild(btn)}
 }
 async function load(){document.getElementById('nprError').textContent='';try{if(window.qmesAuthDataReady&&window.qmesAuthDataReady.wait)await window.qmesAuthDataReady.wait();var res=await fetch('/api/qmes/work-orders',{credentials:'same-origin',cache:'no-store'}),json=await res.json();if(!res.ok||!json.success)throw Error(json.message||'조회 실패');allRows=Array.isArray(json.data)?json.data:[];filter()}catch(e){document.getElementById('nprError').textContent='조회 실패: '+e.message}}

 function close(){panel.classList.remove('active');menu.classList.remove('active')}
 menu.dataset.page='namo-production-result-panel';menu.addEventListener('click',function(e){e.stopPropagation();document.querySelectorAll('.menu').forEach(x=>x.classList.remove('active'));document.querySelectorAll('.module-page').forEach(x=>x.classList.remove('active'));panel.classList.add('active');menu.classList.add('active');load()});
 document.getElementById('nprRows').addEventListener('click',function(e){if(!e.target.closest('.nprWorkLink'))return;close();document.querySelector('#sidebar .menu[data-page="work"]')?.click()});
 document.getElementById('nprRefresh').onclick=load;
 document.getElementById('nprDateToggle').onclick=()=>{var p=document.getElementById('nprDatePopover');p.hidden=!p.hidden};
 document.getElementById('nprDateApply').onclick=()=>{document.getElementById('nprDatePopover').hidden=true;filter()};
 document.getElementById('nprDateClear').onclick=()=>{document.getElementById('nprStart').value='';document.getElementById('nprEnd').value='';document.getElementById('nprDatePopover').hidden=true;filter()};
 document.getElementById('nprCollapse').onclick=()=>{var wrap=panel.querySelector('.npr-table-wrap'),pages=document.getElementById('nprPages'),hidden=wrap.hidden;wrap.hidden=!hidden;pages.hidden=!hidden;document.getElementById('nprCollapse').textContent=hidden?'⌃':'⌄'};

 document.getElementById('nprReset').onclick=()=>{panel.querySelectorAll('input,select').forEach(el=>el.value='');filter()};
 panel.querySelectorAll('input,select').forEach(el=>el.addEventListener('change',filter));
 document.getElementById('nprExport').onclick=()=>{var headers=['No.','작업일자','작업지시번호','제품명','생산 LOT NO','계획수량(kg)','실제 생산수량(kg)','달성률','작업상태'];var lines=[headers,...[...document.querySelectorAll('#nprRows tr')].map(tr=>[...tr.cells].map(td=>td.textContent))];var csv='\uFEFF'+lines.map(row=>row.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n');var a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='생산실적현황.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};

 document.addEventListener('click',e=>{if(panel.classList.contains('active')&&e.target.closest('.menu:not(#namo-production-result-menu)'))close()},true);
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
})();